const useLocal = () => {
  const [local, setLocal] = useState<Problem[]>(() => { try { return JSON.parse(localStorage.getItem('cp-problems') || 'null') || demoProblems; } catch { return demoProblems; } });
  useEffect(() => { localStorage.setItem('cp-problems', JSON.stringify(local)); }, [local]);
  return [local, setLocal] as const;
};

type LocalUser = { name: string; email: string };
type Collaborator = { id: string; name: string; email: string; role: 'You' | 'Member'; status: 'Active' | 'Invited'; solved: number; streak: number };
type ChatMessage = { id: string; author: string; text: string; time: string };
type CollaborationState = { members: Collaborator[]; pinnedProblemId: number | null; messages: ChatMessage[] };

const defaultCollaboration = (user: LocalUser): CollaborationState => ({
  members: [
    { id: 'owner', name: user.name, email: user.email, role: 'You', status: 'Active', solved: 0, streak: 6 },
    { id: 'anika', name: 'Anika Sharma', email: 'anika@example.com', role: 'Member', status: 'Active', solved: 34, streak: 8 },
    { id: 'rohan', name: 'Rohan Mehta', email: 'rohan@example.com', role: 'Member', status: 'Active', solved: 29, streak: 5 },
  ],
  pinnedProblemId: 2,
  messages: [
    { id: 'welcome', author: 'Anika Sharma', text: 'I pinned a medium DP problem for our next study sprint.', time: '09:42' },
    { id: 'hint', author: 'Rohan Mehta', text: 'Nice. I will share a binary search hint after lunch.', time: '09:48' },
  ],
});

const useCollaboration = (user: LocalUser) => {
  const [state, setState] = useState<CollaborationState>(() => {
    try {
      const saved = JSON.parse(localStorage.getItem('cp-collaboration') || 'null') as CollaborationState | null;
      return saved?.members?.length ? saved : defaultCollaboration(user);
    } catch {
      return defaultCollaboration(user);
    }
  });
  useEffect(() => {
    setState(current => {
      const owner = current.members.find(member => member.id === 'owner');
      if (!owner || owner.name === user.name && owner.email === user.email) return current;
      return { ...current, members: current.members.map(member => member.id === 'owner' ? { ...member, name: user.name, email: user.email } : member) };
    });
  }, [user.email, user.name]);
  useEffect(() => { localStorage.setItem('cp-collaboration', JSON.stringify(state)); }, [state]);
  return [state, setState] as const;
};

function Login({ onLogin }: { onLogin: (user: LocalUser) => void }) {
  const [mode, setMode] = useState<'signin' | 'create'>('signin');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const submit = () => {
    if (!email.trim() || password.length < 4 || (mode === 'create' && !name.trim())) return;
    const saved = JSON.parse(localStorage.getItem('cp-user') || 'null') as LocalUser | null;
    const user = mode === 'create' ? { name: name.trim(), email: email.trim() } : saved?.email === email.trim() ? saved : { name: email.split('@')[0], email: email.trim() };
    localStorage.setItem('cp-user', JSON.stringify(user));
    onLogin(user);
  };
  return <div className="grain flex min-h-[100dvh] items-center justify-center bg-sidebar px-5 py-10 text-sidebar-foreground">
    <div className="grid w-full max-w-4xl overflow-hidden rounded-2xl border border-sidebar-border bg-sidebar-accent shadow-2xl md:grid-cols-[.9fr_1.1fr]">
      <div className="hidden flex-col justify-between bg-sidebar-primary p-10 text-sidebar-primary-foreground md:flex">
        <div><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-sidebar-primary-foreground/15"><Code2 size={23}/></div><p className="mono mt-5 text-[10px] uppercase tracking-[.2em] opacity-75">CP Companion</p><h1 className="mt-8 text-4xl font-bold leading-tight tracking-[-.05em]">Practice with<br/>intent.</h1><p className="mt-4 max-w-xs text-sm leading-6 opacity-75">A quiet workspace for the problems between you and your next breakthrough.</p></div>
        <p className="mono text-[10px] uppercase tracking-[.16em] opacity-60">Local-first · private to this browser</p>
      </div>
      <div className="bg-card p-7 text-foreground sm:p-10"><div className="flex items-center gap-3 md:hidden"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary text-primary-foreground"><Code2 size={19}/></div><span className="font-bold">CP Companion</span></div><p className="mono mt-8 text-[10px] font-bold uppercase tracking-[.18em] text-accent md:mt-0">Welcome back</p><h2 className="mt-3 text-3xl font-bold tracking-[-.04em]">{mode === 'signin' ? 'Pick up where you left off.' : 'Create your local profile.'}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Your practice data stays on this device. No account leaves your browser.</p>
        <div className="mt-7 flex rounded-lg bg-muted p-1"><button onClick={()=>setMode('signin')} className={`flex-1 rounded-md py-2 text-xs font-semibold ${mode==='signin'?'bg-card shadow-sm':''}`}>Sign in</button><button onClick={()=>setMode('create')} className={`flex-1 rounded-md py-2 text-xs font-semibold ${mode==='create'?'bg-card shadow-sm':''}`}>Create profile</button></div>
        <div className="mt-6 space-y-4">{mode==='create'&&<label className="block text-xs font-semibold">Name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Your name" className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/></label>}<label className="block text-xs font-semibold">Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/></label><label className="block text-xs font-semibold">Passcode<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 4 characters" className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/></label><button onClick={submit} disabled={!email.trim()||password.length<4||(mode==='create'&&!name.trim())} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-3 text-sm font-bold text-primary-foreground disabled:opacity-50">{mode==='signin'?<LogIn size={16}/>:<Plus size={16}/>} {mode==='signin'?'Enter workspace':'Create local profile'}</button></div>
        <p className="mt-5 text-center text-[11px] text-muted-foreground">This is a local course project mode — there is no remote authentication.</p>
      </div>
    </div>
  </div>;
}

