function Page({ eyebrow, title, description, children, action }: { eyebrow: string; title: React.ReactNode; description?: string; children: React.ReactNode; action?: React.ReactNode }) {
  return <div className="page-in mx-auto max-w-[1440px] px-5 py-8 md:px-10 md:py-10"><div className="mb-9 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mono mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-accent">{eyebrow}</p><h1 className="text-3xl font-bold tracking-[-.04em] md:text-[40px]">{title}</h1>{description&&<p className="mt-2 max-w-xl text-sm text-muted-foreground">{description}</p>}</div>{action}</div>{children}</div>;
}
function Stat({ label, value, sub, icon: Icon, accent=false }: {label:string;value:string|number;sub:string;icon: typeof Target;accent?:boolean}) { return <div className={`rounded-xl border p-5 ${accent?'border-accent/30 bg-accent/[.06]':'border-border bg-card'}`}><div className="flex items-start justify-between"><div><p className="text-xs text-muted-foreground">{label}</p><p data-testid={`text-stat-${label.toLowerCase().replace(' ','-')}`} className="mt-2 text-3xl font-bold tracking-tight">{value}</p></div><div className={`rounded-lg p-2 ${accent?'bg-accent text-accent-foreground':'bg-muted text-muted-foreground'}`}><Icon size={17}/></div></div><p className="mt-3 text-[11px] text-muted-foreground">{sub}</p></div>; }
function Difficulty({ value }: {value: string}) { return <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${value==='Easy'?'bg-accent/10 text-accent':value==='Medium'?'bg-[#d68a1b]/10 text-[#b56d07]':'bg-destructive/10 text-destructive'}`}>{value}</span>; }
function Empty({ title, text, icon: Icon=Database }: {title:string;text:string;icon?:typeof Database}) { return <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-border bg-card/50 px-6 py-16 text-center"><div className="mb-4 rounded-xl bg-muted p-3 text-muted-foreground"><Icon size={22}/></div><h3 className="font-semibold">{title}</h3><p className="mt-1 max-w-xs text-sm text-muted-foreground">{text}</p></div>; }

function Overview() {
  const { data, isLoading, isError } = useListProblems(undefined, { query: { queryKey: getListProblemsQueryKey() } });
  const { data: analytics } = useGetAnalyticsSummary({ query: { queryKey: getGetAnalyticsSummaryQueryKey() } });
  const [local] = useLocal(); const problems = data?.length ? data : local; const solved=analytics?.solved ?? problems.filter(p=>p.status==='Solved').length; const total=analytics?.total ?? problems.length; const favorites=analytics?.favorites ?? problems.filter(p=>p.favorite).length; const weekly=analytics?.weeklyCompleted ?? 17; const goal=analytics?.weeklyGoal ?? 25;
  return <Page eyebrow="Monday, 12 May 2025" title={<>Keep the streak<br/><span className="text-accent">alive.</span></>} description="A focused workspace for the problems between you and your next breakthrough."><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Problems solved" value={solved} sub={`of ${total} in your library`} icon={Check} accent/><Stat label="This week" value={`${weekly}/${goal}`} sub={`${Math.round((weekly/goal)*100)}% of weekly goal`} icon={Target}/><Stat label="Favorites" value={favorites} sub="bookmarked for later" icon={Heart}/><Stat label="Current streak" value="6 days" sub="best: 12 days" icon={Flame}/></div>
    <div className="mt-8 grid gap-5 xl:grid-cols-[1.5fr_1fr]"><section className="rounded-xl border border-border bg-card p-5 md:p-6"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Weekly momentum</h2><p className="mt-1 text-xs text-muted-foreground">Solved problems · last 7 days</p></div><Link data-testid="link-view-analytics" href="/analytics" className="text-xs font-semibold text-accent hover:underline">View analytics <ChevronRight className="inline" size={13}/></Link></div><div className="mt-6 h-[190px]">{isLoading?<div className="h-full animate-pulse rounded-lg bg-muted"/>:<ResponsiveContainer width="100%" height="100%"><BarChart data={analytics?.weeklyActivity ?? demoActivity} barCategoryGap="35%"><CartesianGrid vertical={false} stroke="hsl(var(--border))"/><XAxis dataKey="day" tick={{fontSize:11,fill:'hsl(var(--muted-foreground))'}} axisLine={false} tickLine={false}/><YAxis hide allowDecimals={false}/><Tooltip cursor={{fill:'hsl(var(--muted))'}} contentStyle={{borderRadius:8,border:'1px solid hsl(var(--border))',background:'hsl(var(--card))',fontSize:12}}/><Bar dataKey="solved" radius={[4,4,1,1]} fill="hsl(var(--accent))"/></BarChart></ResponsiveContainer>}</div></section>
      <section className="rounded-xl border border-border bg-sidebar p-5 text-sidebar-foreground md:p-6"><div className="flex items-center gap-2 text-sidebar-primary"><Sparkles size={17}/><span className="mono text-[10px] font-bold uppercase tracking-[.16em]">Next up</span></div><h2 className="mt-7 text-2xl font-bold tracking-tight">Close the gap<br/>on <span className="text-sidebar-primary">graphs.</span></h2><p className="mt-3 text-sm leading-6 text-sidebar-foreground/55">You have 4 graph problems waiting. A focused 25-minute session will make a dent.</p><Link data-testid="link-start-revision" href="/revision" className="mt-7 flex items-center justify-between rounded-lg bg-sidebar-primary px-4 py-3 text-sm font-bold text-sidebar-primary-foreground transition-transform hover:translate-x-1">Open revision queue <ChevronRight size={17}/></Link></section></div>
    <div className="mt-8 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold">Recent problems</h2><p className="mt-1 text-xs text-muted-foreground">Your latest additions and attempts</p></div><Link data-testid="link-browse-library" href="/problems" className="text-xs font-semibold text-accent">Browse library <ChevronRight className="inline" size={13}/></Link></div>{isError&&<div className="mb-3 rounded-lg border border-destructive/30 bg-destructive/5 p-3 text-xs text-destructive">Showing your saved local library while the API reconnects.</div>}{problems.slice(0,4).map(p=><ProblemRow key={p.id} problem={p}/>)}</section><section><div className="mb-4"><h2 className="font-semibold">Focus topics</h2><p className="mt-1 text-xs text-muted-foreground">Where your practice is concentrated</p></div><div className="rounded-xl border border-border bg-card p-5">{['Dynamic Programming','Graphs','Arrays','Strings'].map((topic,i)=><div key={topic} className="mb-4 last:mb-0"><div className="mb-2 flex justify-between text-xs"><span>{topic}</span><span className="mono text-muted-foreground">{[32,24,18,11][i]}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="bar h-full rounded-full bg-accent" style={{width:`${[82,64,48,31][i]}%`}}/></div></div>)}</div></section></div>
  </Page>;
}
function ProblemRow({ problem:p, onToggle, onEdit, onDelete, onSolve }: {problem:Problem;onToggle?:()=>void;onEdit?:()=>void;onDelete?:()=>void;onSolve?:()=>void}) { return <div data-testid={`row-problem-${p.id}`} className="group mb-2 flex items-center gap-3 rounded-xl border border-border bg-card p-4 transition-colors hover:border-accent/40"><button aria-label={`Favorite ${p.title}`} data-testid={`button-favorite-${p.id}`} onClick={onToggle} className={`shrink-0 ${p.favorite?'text-[#d68a1b]':'text-muted-foreground/35 hover:text-[#d68a1b]'}`}><Heart size={16} fill={p.favorite?'currentColor':'none'}/></button><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="truncate text-sm font-semibold">{p.title}</span><Difficulty value={p.difficulty}/></div><div className="mt-1 flex items-center gap-2 text-[11px] text-muted-foreground"><span>{p.platform}</span><span className="text-border">/</span><span>{p.topics.slice(0,2).join(' · ')}</span></div></div><div className={`hidden items-center gap-1.5 text-[11px] sm:flex ${p.status==='Solved'?'text-accent':'text-muted-foreground'}`}><span className={`h-1.5 w-1.5 rounded-full ${p.status==='Solved'?'bg-accent':'bg-muted-foreground/40'}`}/>{p.status}</div><div className="flex items-center gap-1 opacity-0 transition-opacity group-hover:opacity-100"><button aria-label={p.status==='Solved'?'Mark unsolved':`Mark ${p.title} solved`} data-testid={`button-solve-${p.id}`} onClick={onSolve} className={`rounded p-1.5 hover:bg-muted ${p.status==='Solved'?'text-accent':'text-muted-foreground'}`}><CheckCircle2 size={15}/></button><button aria-label={`Edit ${p.title}`} data-testid={`button-edit-${p.id}`} onClick={onEdit} className="rounded p-1.5 text-muted-foreground hover:bg-muted hover:text-accent"><Pencil size={15}/></button><button aria-label={`Delete ${p.title}`} data-testid={`button-delete-${p.id}`} onClick={onDelete} className="rounded p-1.5 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"><Trash2 size={15}/></button>{p.solutionLink&&<a aria-label={`Open solution for ${p.title}`} data-testid={`link-solution-${p.id}`} href={p.solutionLink} target="_blank" rel="noreferrer" className="rounded p-1.5 text-muted-foreground hover:bg-muted hover:text-accent"><ExternalLink size={15}/></a>}</div></div>; }

function Problems() {
  const { data, isLoading, isError } = useListProblems(undefined, { query: { queryKey: getListProblemsQueryKey() } }); const [local,setLocal]=useLocal(); const apiProblems=data?.length?data:local; const update=useUpdateProblem(); const del=useDeleteProblem(); const create=useCreateProblem(); const qc=useQueryClient(); const [search,setSearch]=useState(''); const [difficulty,setDifficulty]=useState('All'); const [status,setStatus]=useState('All'); const [favorites,setFavorites]=useState(false); const [showForm,setShowForm]=useState(false); const [editing,setEditing]=useState<Problem|null>(null); const [form,setForm]=useState({title:'',platform:'LeetCode',difficulty:'Medium' as ProblemDifficulty,topics:'',solutionLink:''});
  const problems=useMemo(()=>apiProblems.filter(p=>(!search||`${p.title} ${p.platform} ${p.topics.join(' ')}`.toLowerCase().includes(search.toLowerCase()))&&(difficulty==='All'||p.difficulty===difficulty)&&(status==='All'||p.status===status)&&(!favorites||p.favorite)),[apiProblems,search,difficulty,status,favorites]);
  const toggle=(p:Problem)=>{const next=!p.favorite; setLocal(xs=>xs.map(x=>x.id===p.id?{...x,favorite:next}:x)); update.mutate({id:p.id,data:{favorite:next}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListProblemsQueryKey()})});};
  const solve=(p:Problem)=>{const next=p.status==='Solved'?'Unsolved':'Solved'; setLocal(xs=>xs.map(x=>x.id===p.id?{...x,status:next}:x)); update.mutate({id:p.id,data:{status:next}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListProblemsQueryKey()})});};
  const remove=(p:Problem)=>{if(!confirm(`Delete “${p.title}” from your library?`))return; setLocal(xs=>xs.filter(x=>x.id!==p.id)); del.mutate({id:p.id},{onSuccess:()=>qc.invalidateQueries({queryKey:getListProblemsQueryKey()})});};
  const openEdit=(p:Problem)=>{setEditing(p);setForm({title:p.title,platform:p.platform,difficulty:p.difficulty,topics:p.topics.join(', '),solutionLink:p.solutionLink||''});setShowForm(true);};
  const add=()=>{if(!form.title.trim())return; const input={title:form.title,difficulty:form.difficulty,platform:form.platform,topics:form.topics.split(',').map(x=>x.trim()).filter(Boolean),solutionLink:form.solutionLink||undefined}; if(editing){const patch={...input};setLocal(xs=>xs.map(x=>x.id===editing.id?{...x,...patch}:x));update.mutate({id:editing.id,data:patch},{onSuccess:()=>qc.invalidateQueries({queryKey:getListProblemsQueryKey()})});}else{create.mutate({data:input},{onSuccess:()=>qc.invalidateQueries({queryKey:getListProblemsQueryKey()}),onError:()=>{const next={...input,id:Date.now(),status:'Unsolved' as const,favorite:false,dateAdded:new Date().toISOString(),attempts:0};setLocal(xs=>[next,...xs]);}})}setEditing(null);setShowForm(false);};
  return <Page eyebrow="Problem library" title="Your problem set." description="Collect the patterns worth remembering. Search by title, platform, or topic." action={<button data-testid="button-add-problem" onClick={()=>setShowForm(true)} className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground hover:opacity-90"><Plus size={16}/> Add problem</button>}>
    {isError&&<div className="mb-5 flex items-center gap-2 rounded-lg border border-[#d68a1b]/30 bg-[#d68a1b]/5 p-3 text-xs text-[#9b5e08]"><Database size={14}/> Offline mode · changes are saved on this device.</div>}
    <div className="mb-5 flex flex-col gap-3 rounded-xl border border-border bg-card p-3 md:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16}/><input data-testid="input-search-problems" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search title, topic, or platform..." className="h-10 w-full rounded-lg bg-muted/50 pl-10 pr-3 text-sm outline-none ring-accent focus:ring-2"/></div><div className="flex gap-2 overflow-x-auto"><select data-testid="select-difficulty-filter" value={difficulty} onChange={e=>setDifficulty(e.target.value)} className="h-10 rounded-lg border border-border bg-card px-3 text-xs outline-none"><option>All</option><option>Easy</option><option>Medium</option><option>Hard</option></select><select data-testid="select-status-filter" value={status} onChange={e=>setStatus(e.target.value)} className="h-10 rounded-lg border border-border bg-card px-3 text-xs outline-none"><option>All</option><option>Solved</option><option>Unsolved</option></select><button data-testid="button-filter-favorites" onClick={()=>setFavorites(!favorites)} className={`flex h-10 items-center gap-2 rounded-lg border px-3 text-xs ${favorites?'border-accent bg-accent/10 text-accent':'border-border text-muted-foreground'}`}><Filter size={14}/> Favorites</button></div></div>
    <div className="mb-4 flex items-center justify-between text-xs text-muted-foreground"><span>{problems.length} problems {search&&`matching “${search}”`}</span><span className="mono">{problems.filter(p=>p.status==='Solved').length} solved</span></div>{isLoading?<div className="space-y-2">{[1,2,3,4].map(i=><div key={i} className="h-[74px] animate-pulse rounded-xl bg-muted"/>)}</div>:problems.length?<div>{problems.map(p=><ProblemRow key={p.id} problem={p} onToggle={()=>toggle(p)} onSolve={()=>solve(p)} onEdit={()=>openEdit(p)} onDelete={()=>remove(p)}/>)}</div>:<Empty title="No problems found" text="Try a different filter or add a problem to your library." icon={Search}/>}
    {showForm&&<div className="fixed inset-0 z-50 flex items-end justify-center bg-sidebar/40 p-0 sm:items-center sm:p-5"><div className="w-full max-w-lg rounded-t-2xl border border-border bg-card p-6 shadow-2xl sm:rounded-2xl"><div className="flex items-center justify-between"><h2 className="text-xl font-bold">{editing?'Edit problem':'Add a problem'}</h2><button aria-label="Close add problem" data-testid="button-close-add-problem" onClick={()=>{setShowForm(false);setEditing(null)}}><X size={19}/></button></div><div className="mt-6 space-y-4"><label className="block text-xs font-semibold">Title<input data-testid="input-problem-title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="e.g. Binary Tree Maximum Path Sum" className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/></label><div className="grid grid-cols-2 gap-3"><label className="text-xs font-semibold">Platform<select data-testid="select-problem-platform" value={form.platform} onChange={e=>setForm({...form,platform:e.target.value})} className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm"><option>LeetCode</option><option>Codeforces</option><option>AtCoder</option><option>NeetCode</option></select></label><label className="text-xs font-semibold">Difficulty<select data-testid="select-problem-difficulty" value={form.difficulty} onChange={e=>setForm({...form,difficulty:e.target.value as ProblemDifficulty})} className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm"><option>Easy</option><option>Medium</option><option>Hard</option></select></label></div><label className="block text-xs font-semibold">Topics <span className="font-normal text-muted-foreground">(comma separated)</span><input data-testid="input-problem-topics" value={form.topics} onChange={e=>setForm({...form,topics:e.target.value})} placeholder="Graphs, BFS, Shortest Path" className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/></label><label className="block text-xs font-semibold">Solution link <span className="font-normal text-muted-foreground">(optional)</span><input data-testid="input-problem-link" value={form.solutionLink} onChange={e=>setForm({...form,solutionLink:e.target.value})} placeholder="https://" className="mt-2 h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/></label><div className="flex gap-3 pt-2"><button data-testid="button-cancel-add-problem" onClick={()=>{setShowForm(false);setEditing(null)}} className="flex-1 rounded-lg border border-border py-2.5 text-sm font-semibold">Cancel</button><button data-testid="button-submit-problem" onClick={add} disabled={!form.title.trim()||create.isPending||update.isPending} className="flex-1 rounded-lg bg-primary py-2.5 text-sm font-semibold text-primary-foreground disabled:opacity-50">{editing?'Save changes':create.isPending?'Adding…':'Add to library'}</button></div></div></div></div>}
  </Page>;
}

function Revision() { const {data,isLoading}=useGetRevisionQueue({query:{queryKey:getGetRevisionQueueQueryKey()}}); const [local]=useLocal(); const queue=data?.length?data:local.filter(p=>p.status==='Unsolved').slice(0,4); return <Page eyebrow="Spaced repetition" title="Revision queue." description="The highest-leverage problems to revisit next, ordered by what will move your understanding forward."><div className="mb-7 grid gap-4 sm:grid-cols-3"><Stat label="Due today" value={queue.length} sub="problems need attention" icon={BrainCircuit} accent/><Stat label="Review rhythm" value="4.2 days" sub="average between reviews" icon={RefreshCw}/><Stat label="Retention" value="78%" sub="across reviewed patterns" icon={Zap}/></div><div className="grid gap-6 lg:grid-cols-[1fr_300px]"><div><div className="mb-4 flex items-center justify-between"><h2 className="font-semibold">Priority stack</h2><span className="mono text-[10px] text-muted-foreground">SORTED BY IMPACT</span></div>{isLoading?<div className="h-48 animate-pulse rounded-xl bg-muted"/>:queue.length?queue.map((p,i)=><div key={p.id} className="mb-3 flex items-center gap-4 rounded-xl border border-border bg-card p-4 transition-all hover:-translate-y-0.5 hover:border-accent/40"><div className="mono flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted text-xs text-muted-foreground">{String(i+1).padStart(2,'0')}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="truncate text-sm font-semibold">{p.title}</h3><Difficulty value={p.difficulty}/></div><p className="mt-1 text-xs text-muted-foreground">{p.platform} · {p.topics.join(' · ')}</p></div><button data-testid={`button-review-${p.id}`} className="hidden rounded-lg bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground sm:block">Review now</button><ChevronRight className="text-muted-foreground sm:hidden" size={17}/></div>):<Empty title="Queue is clear" text="Nice work. Solve a few more problems and the queue will build itself." icon={Check}/>}</div><aside className="rounded-xl border border-border bg-card p-5"><p className="mono text-[10px] uppercase tracking-[.15em] text-accent">Why this order?</p><h3 className="mt-4 font-semibold">Practice with intent.</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Your queue balances recency, difficulty, attempts, and the topics you have seen least recently.</p><div className="mt-6 border-t border-border pt-4 text-xs text-muted-foreground"><div className="flex justify-between"><span>Next review window</span><span className="font-semibold text-foreground">Today, 7:30 PM</span></div></div></aside></div></Page>; }

function Analytics() { const {data,isLoading,isError}=useGetAnalyticsSummary({query:{queryKey:getGetAnalyticsSummaryQueryKey()}}); const summary=data??{total:42,solved:27,favorites:8,weeklyGoal:25,weeklyCompleted:17,difficulty:[{name:'Easy',value:12},{name:'Medium',value:21},{name:'Hard',value:9}],topics:[{name:'Dynamic Programming',value:11},{name:'Graphs',value:8},{name:'Arrays',value:7},{name:'Strings',value:6}],weeklyActivity:demoActivity}; const pct=Math.round(summary.solved/Math.max(summary.total,1)*100); return <Page eyebrow="Practice analytics" title="See the signal." description="Patterns in your practice, distilled into something you can act on."><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Total problems" value={summary.total} sub="across all platforms" icon={BookOpen}/><Stat label="Solved" value={`${summary.solved} / ${summary.total}`} sub={`${pct}% completion rate`} icon={Check} accent/><Stat label="Weekly progress" value={`${summary.weeklyCompleted}/${summary.weeklyGoal}`} sub="problems toward your goal" icon={Target}/><Stat label="Favorites" value={summary.favorites} sub="saved for deep review" icon={Heart}/></div>{isError&&<p className="mt-5 text-xs text-muted-foreground">Analytics preview is using local estimates while the server is unavailable.</p>}<div className="mt-8 grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><section className="rounded-xl border border-border bg-card p-5 md:p-6"><h2 className="font-semibold">Weekly activity</h2><p className="mt-1 text-xs text-muted-foreground">Your solving cadence</p><div className="mt-6 h-[245px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={summary.weeklyActivity} barCategoryGap="28%"><CartesianGrid vertical={false} stroke="hsl(var(--border))"/><XAxis dataKey="day" tick={{fontSize:11,fill:'hsl(var(--muted-foreground))'}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fontSize:11,fill:'hsl(var(--muted-foreground))'}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{borderRadius:8,border:'1px solid hsl(var(--border))',background:'hsl(var(--card))',fontSize:12}}/><Bar dataKey="solved" fill="hsl(var(--accent))" radius={[5,5,1,1]}/></BarChart></ResponsiveContainer></div></section><section className="rounded-xl border border-border bg-card p-5 md:p-6"><h2 className="font-semibold">Difficulty mix</h2><p className="mt-1 text-xs text-muted-foreground">What you are taking on</p><div className="mt-4 h-[190px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={summary.difficulty} dataKey="value" nameKey="name" innerRadius={55} outerRadius={78} paddingAngle={4}>{summary.difficulty.map((_,i)=><Cell key={i} fill={['hsl(var(--accent))','#d68a1b','hsl(var(--destructive))'][i%3]}/>)}</Pie><Tooltip contentStyle={{borderRadius:8,border:'1px solid hsl(var(--border))',background:'hsl(var(--card))',fontSize:12}}/></PieChart></ResponsiveContainer></div><div className="space-y-2">{summary.difficulty.map((d,i)=><div className="flex items-center justify-between text-xs" key={d.name}><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full" style={{background:['hsl(var(--accent))','#d68a1b','hsl(var(--destructive))'][i%3]}}/>{d.name}</span><span className="mono text-muted-foreground">{d.value}</span></div>)}</div></section></div><section className="mt-5 rounded-xl border border-border bg-card p-5 md:p-6"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Topic coverage</h2><p className="mt-1 text-xs text-muted-foreground">The patterns you are building muscle memory around</p></div><Link data-testid="link-analytics-library" href="/problems" className="text-xs font-semibold text-accent">Practice a topic <ChevronRight className="inline" size={13}/></Link></div><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{summary.topics.map(t=><div key={t.name} className="rounded-lg bg-muted/60 p-4"><p className="truncate text-xs font-semibold">{t.name}</p><p className="mt-2 mono text-lg">{t.value}<span className="ml-1 text-[10px] text-muted-foreground">solved</span></p><div className="mt-3 h-1 rounded-full bg-border"><div className="h-full rounded-full bg-accent" style={{width:`${Math.min(100,t.value*7)}%`}}/></div></div>)}</div></section></Page>; }

function Contest() { const [started,setStarted]=useState(false); const [time,setTime]=useState(90*60); useEffect(()=>{if(!started)return; const id=setInterval(()=>setTime(t=>Math.max(0,t-1)),1000);return()=>clearInterval(id)},[started]); const mins=Math.floor(time/60).toString().padStart(2,'0'), secs=(time%60).toString().padStart(2,'0'); const tasks: Array<[string,string,string,boolean]>=[['A','Warm-up: Prefix Sums','Easy',true],['B','The Missing Permutation','Medium',false],['C','Island Hopping','Medium',false],['D','Optimal Routes','Hard',false]]; return <Page eyebrow="Virtual contest" title="Make it count." description="A quiet room for a timed set. No leaderboard, no noise — just the next problem."><div className="grid-paper overflow-hidden rounded-2xl border border-border bg-card"><div className="flex flex-col justify-between gap-5 border-b border-border p-6 md:flex-row md:items-center md:p-8"><div><div className="flex items-center gap-2 text-accent"><Command size={18}/><span className="mono text-[10px] uppercase tracking-[.16em]">solo arena · set 04</span></div><h2 className="mt-4 text-2xl font-bold tracking-tight">The Pattern Hunt</h2><p className="mt-2 max-w-lg text-sm text-muted-foreground">Four carefully chosen problems. Ninety minutes. The goal is not speed — it is recognition.</p></div><div className="flex items-center gap-4"><div className="rounded-xl border border-border bg-background px-5 py-3 text-center"><p className="mono text-[9px] uppercase tracking-widest text-muted-foreground">Time left</p><p className={`mono mt-1 text-2xl font-bold ${started&&time<300?'text-destructive':'text-foreground'}`}>{mins}:{secs}</p></div><button data-testid="button-contest-start" onClick={()=>setStarted(!started)} className={`rounded-lg px-4 py-3 text-sm font-bold ${started?'border border-border bg-background':'bg-primary text-primary-foreground'}`}>{started?'Pause session':'Start contest'}</button></div></div><div className="p-5 md:p-8"><div className="mb-5 flex items-center justify-between"><h3 className="font-semibold">Problem set</h3><span className="mono text-[10px] text-muted-foreground">0 / 4 SUBMITTED</span></div><div className="space-y-2">{tasks.map(([letter,title,diff,done])=><div key={letter} className="flex items-center gap-4 rounded-xl border border-border bg-background p-4"><span className={`mono flex h-9 w-9 items-center justify-center rounded-lg text-sm font-bold ${done?'bg-accent text-accent-foreground':'bg-muted text-muted-foreground'}`}>{letter}</span><div className="flex-1"><p className="text-sm font-semibold">{title}</p><div className="mt-1"><Difficulty value={diff}/></div></div><div className="flex items-center gap-3">{done&&<span className="flex items-center gap-1 text-[11px] text-accent"><Check size={14}/> Solved</span>}<button data-testid={`button-contest-open-${letter}`} className="rounded-lg border border-border px-3 py-2 text-xs font-semibold hover:border-accent">Open <ChevronRight className="ml-1 inline" size={13}/></button></div></div>)}</div></div></div></Page>; }

function Collaborator({ user }: { user: LocalUser }) {
  const { data, isError } = useListProblems(undefined, { query: { queryKey: getListProblemsQueryKey() } });
  const [localProblems] = useLocal();
  const problems = data?.length ? data : localProblems;
  const [state, setState] = useCollaboration(user);
  const [invite, setInvite] = useState('');
  const [message, setMessage] = useState('');
  const [notice, setNotice] = useState('');
  const solvedCount = problems.filter(problem => problem.status === 'Solved').length;
  const pinned = problems.find(problem => problem.id === state.pinnedProblemId) ?? problems[0];
  const members = useMemo(() => state.members.map(member => member.id === 'owner' ? { ...member, solved: solvedCount } : member).sort((a, b) => b.solved - a.solved), [solvedCount, state.members]);
  const inviteFriend = () => {
    const email = invite.trim().toLowerCase();
    if (!email || !email.includes('@') || state.members.some(member => member.email === email)) return;
    const name = email.split('@')[0].replace(/[._-]/g, ' ').replace(/\b\w/g, char => char.toUpperCase());
    setState(current => ({ ...current, members: [...current.members, { id: `invite-${Date.now()}`, name, email, role: 'Member', status: 'Invited', solved: 0, streak: 0 }] }));
    setInvite('');
    setNotice(`Invite prepared for ${email}.`);
  };
  const postMessage = () => {
    const text = message.trim();
    if (!text) return;
    const now = new Date();
    const time = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setState(current => ({ ...current, messages: [...current.messages, { id: `message-${Date.now()}`, author: user.name, text, time }] }));
    setMessage('');
  };
  const copyInviteLink = () => {
    navigator.clipboard?.writeText(`${window.location.origin}/collaborator`);
    setNotice('Collaboration link copied.');
  };
  return <Page eyebrow="Study together" title={<>Your shared<br/><span className="text-accent">practice room.</span></>} description="Invite friends, choose one problem to solve together, and keep each other moving.">
    {isError && <div className="mb-5 flex items-center gap-2 rounded-lg border border-[#d68a1b]/30 bg-[#d68a1b]/5 p-3 text-xs text-[#9b5e08]"><Database size={14}/> Offline mode · collaboration activity is saved on this device.</div>}
    <div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
      <section className="rounded-xl border border-border bg-card p-5 md:p-6">
        <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><div className="flex items-center gap-2 text-accent"><Users size={17}/><span className="mono text-[10px] font-bold uppercase tracking-[.16em]">Collaborator</span></div><h2 className="mt-3 text-xl font-bold">Build your study circle.</h2><p className="mt-1 text-sm text-muted-foreground">Everyone’s progress is visible here.</p></div><button data-testid="button-copy-collaboration-link" onClick={copyInviteLink} className="flex items-center justify-center gap-2 rounded-lg border border-border px-3 py-2 text-xs font-semibold hover:border-accent"><Copy size={14}/> Copy room link</button></div>
        <div className="mt-6 flex gap-2"><input data-testid="input-invite-friend" value={invite} onChange={e => setInvite(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') inviteFriend(); }} type="email" placeholder="friend@example.com" className="h-11 min-w-0 flex-1 rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/><button data-testid="button-invite-friend" onClick={inviteFriend} disabled={!invite.trim()} className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground disabled:opacity-50"><UserPlus size={16}/> <span className="hidden sm:inline">Invite</span></button></div>
        {notice && <p data-testid="text-collaboration-notice" className="mt-3 text-xs text-accent">{notice}</p>}
        <div className="mt-6 space-y-2">{state.members.map(member => <div key={member.id} className="flex items-center gap-3 rounded-lg bg-muted/55 p-3"><div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-xs font-bold ${member.id === 'owner' ? 'bg-primary text-primary-foreground' : 'bg-accent/15 text-accent'}`}>{member.name.slice(0, 2).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{member.name} {member.role === 'You' && <span className="ml-1 text-[10px] font-normal text-muted-foreground">(you)</span>}</p><p className="truncate text-[11px] text-muted-foreground">{member.email}</p></div><span className={`hidden rounded-full px-2 py-1 text-[10px] font-semibold sm:inline ${member.status === 'Active' ? 'bg-accent/10 text-accent' : 'bg-[#d68a1b]/10 text-[#b56d07]'}`}>{member.status}</span><span className="text-right"><span className="mono block text-sm font-bold">{member.id === 'owner' ? solvedCount : member.solved}</span><span className="text-[10px] text-muted-foreground">solved</span></span></div>)}</div>
      </section>
      <section className="rounded-xl border border-accent/25 bg-accent/[.06] p-5 md:p-6">
        <div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2 text-accent"><Pin size={16} fill="currentColor"/><span className="mono text-[10px] font-bold uppercase tracking-[.16em]">Pinned for everyone</span></div><h2 className="mt-3 text-xl font-bold">{pinned ? pinned.title : 'Choose a shared problem'}</h2><p className="mt-2 text-sm text-muted-foreground">{pinned ? `${pinned.platform} · ${pinned.topics.join(' · ')}` : 'Select a problem from your library to start together.'}</p></div><Pin className="shrink-0 text-accent" size={22} fill="currentColor"/></div>
        {pinned && <div className="mt-5 flex items-center justify-between rounded-lg border border-accent/20 bg-card/70 p-3"><Difficulty value={pinned.difficulty}/><span className="text-xs font-semibold text-accent">{pinned.status === 'Solved' ? 'You solved this' : 'Ready to solve'}</span></div>}
        <label className="mt-5 block text-xs font-semibold">Change pinned problem<select data-testid="select-pinned-problem" value={pinned?.id ?? ''} onChange={e => setState(current => ({ ...current, pinnedProblemId: Number(e.target.value) }))} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"><option value="" disabled>Select a problem</option>{problems.map(problem => <option key={problem.id} value={problem.id}>{problem.title}</option>)}</select></label>
        {pinned?.solutionLink && <a href={pinned.solutionLink} target="_blank" rel="noreferrer" className="mt-4 inline-flex items-center gap-2 text-xs font-semibold text-accent hover:underline"><Link2 size={14}/> Open problem</a>}
      </section>
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
      <section className="rounded-xl border border-border bg-card p-5 md:p-6"><div className="flex items-center justify-between"><div><div className="flex items-center gap-2"><MessageCircle size={17} className="text-accent"/><h2 className="font-semibold">Room chat</h2></div><p className="mt-1 text-xs text-muted-foreground">Share hints without giving away the whole solution.</p></div><span className="mono text-[10px] text-muted-foreground">{state.messages.length} NOTES</span></div><div className="mt-5 max-h-[270px] space-y-3 overflow-y-auto pr-1">{state.messages.map(chat => <div key={chat.id} className={`flex gap-3 ${chat.author === user.name ? 'flex-row-reverse text-right' : ''}`}><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted text-[10px] font-bold">{chat.author.slice(0, 2).toUpperCase()}</div><div className={`max-w-[82%] rounded-xl px-3 py-2 ${chat.author === user.name ? 'bg-primary text-primary-foreground' : 'bg-muted/70'}`}><p className="text-[11px] font-bold opacity-75">{chat.author}</p><p className="mt-1 text-sm">{chat.text}</p><p className="mt-1 text-[10px] opacity-55">{chat.time}</p></div></div>)}</div><div className="mt-5 flex gap-2 border-t border-border pt-4"><input data-testid="input-collaboration-message" value={message} onChange={e => setMessage(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') postMessage(); }} placeholder="Write a message or hint..." className="h-11 min-w-0 flex-1 rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-accent"/><button data-testid="button-send-collaboration-message" onClick={postMessage} disabled={!message.trim()} aria-label="Send message" className="flex h-11 w-11 items-center justify-center rounded-lg bg-primary text-primary-foreground disabled:opacity-50"><Send size={16}/></button></div></section>
      <section className="rounded-xl border border-border bg-card p-5 md:p-6"><div className="flex items-center justify-between"><div><div className="flex items-center gap-2"><Trophy size={17} className="text-accent"/><h2 className="font-semibold">Progress leaderboard</h2></div><p className="mt-1 text-xs text-muted-foreground">Solved problems across the room.</p></div><span className="mono text-[10px] text-muted-foreground">LIVE</span></div><div className="mt-5 space-y-2">{members.map((member, index) => <div key={member.id} className={`flex items-center gap-3 rounded-lg border p-3 ${index === 0 ? 'border-accent/25 bg-accent/[.06]' : 'border-transparent bg-muted/45'}`}><span className="mono w-5 text-center text-xs font-bold text-muted-foreground">{index + 1}</span><div className="flex h-8 w-8 items-center justify-center rounded-full bg-sidebar text-[10px] font-bold text-sidebar-foreground">{member.name.slice(0, 2).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{member.name}{index === 0 && <Crown className="ml-1 inline text-[#d68a1b]" size={13} fill="currentColor"/>}</p><p className="text-[10px] text-muted-foreground">{member.streak ? `${member.streak} day streak` : 'Just joined'}</p></div><span className="mono text-sm font-bold">{member.solved}<span className="ml-1 text-[10px] font-normal text-muted-foreground">solved</span></span></div>)}</div><div className="mt-5 rounded-lg bg-muted/55 p-3 text-xs text-muted-foreground"><span className="font-semibold text-foreground">Keep going.</span> Solve a problem in your library to move up the board.</div></section>
    </div>
  </Page>;
}

function Settings() {
  const [dark,setDark]=useState(document.documentElement.classList.contains('dark'));
  const [,setLocation]=useLocation();
  const [message,setMessage]=useState('');
  const [local,setLocal]=useLocal();
  const theme=(v:boolean)=>{setDark(v);document.documentElement.classList.toggle('dark',v);localStorage.setItem('cp-theme',v?'dark':'light');setMessage('Theme preference saved.');};
  const download=(content:string, name:string, type:string)=>{const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href);};
  const backup=()=>{download(JSON.stringify(local,null,2),'cp-companion-backup.json','application/json');setMessage('JSON backup downloaded.');};
  const exportCsv=()=>{const headers=['id','title','difficulty','platform','topics','status','favorite','notes','dateAdded','solutionLink','solvedDate','attempts'];const rows=local.map(p=>headers.map(h=>{const value=p[h as keyof Problem];const text=Array.isArray(value)?value.join('|'):String(value??'');return `"${text.replaceAll('"','""')}"`;}).join(','));download([headers.join(','),...rows].join('\n'),'cp-companion-problems.csv','text/csv');setMessage('CSV export downloaded.');};
  const importFile=(file:File)=>{const reader=new FileReader();reader.onload=()=>{try{const text=String(reader.result);let imported:Problem[];if(file.name.toLowerCase().endsWith('.json')) imported=JSON.parse(text) as Problem[];else{const [header,...lines]=text.trim().split(/\r?\n/);const keys=header.split(',').map(k=>k.replaceAll('"',''));imported=lines.map((line,index)=>{const values=(line.match(/(".*?"|[^",]+)(?=,|$)/g)||[]).map(v=>v.replace(/^"|"$/g,'').replaceAll('""','"'));const row=Object.fromEntries(keys.map((key,i)=>[key,values[i]||'']));return {...row,id:Number(row.id)||Date.now()+index,topics:String(row.topics||'').split('|').filter(Boolean),favorite:row.favorite==='true',status:row.status==='Solved'?'Solved':'Unsolved',attempts:Number(row.attempts)||0} as Problem;});}if(!Array.isArray(imported)||!imported.length)throw new Error('empty');setLocal(imported);setMessage(`${imported.length} problems imported.`);}catch{setMessage('Could not read that backup file.');}};reader.readAsText(file);};
  return <Page eyebrow="Workspace preferences" title="Make it yours." description="Tune your study environment and keep your practice data safe."><div className="max-w-3xl space-y-5"><section className="rounded-xl border border-border bg-card p-5 md:p-6"><div className="flex items-start gap-4"><div className="rounded-lg bg-muted p-2.5"><Sun size={18}/></div><div><h2 className="font-semibold">Appearance</h2><p className="mt-1 text-sm text-muted-foreground">Choose the atmosphere you want to return to.</p></div></div><div className="mt-6 grid grid-cols-2 gap-3"><button data-testid="button-theme-light" onClick={()=>theme(false)} className={`rounded-xl border p-4 text-left ${!dark?'border-accent bg-accent/5':''}`}><div className="h-14 rounded-lg border border-border bg-[#f5f1e8] p-2"><div className="h-2 w-1/2 rounded bg-[#252a3b]"/><div className="mt-2 h-2 w-3/4 rounded bg-[#d9d3c7]"/></div><p className="mt-3 text-xs font-semibold">Light / parchment</p></button><button data-testid="button-theme-dark" onClick={()=>theme(true)} className={`rounded-xl border p-4 text-left ${dark?'border-accent bg-accent/5':''}`}><div className="h-14 rounded-lg border border-[#33394c] bg-[#171a27] p-2"><div className="h-2 w-1/2 rounded bg-[#e9e5d9]"/><div className="mt-2 h-2 w-3/4 rounded bg-[#33394c]"/></div><p className="mt-3 text-xs font-semibold">Dark / midnight</p></button></div></section><section className="rounded-xl border border-border bg-card p-5 md:p-6"><div className="flex items-start gap-4"><div className="rounded-lg bg-muted p-2.5"><Database size={18}/></div><div><h2 className="font-semibold">Data backup</h2><p className="mt-1 text-sm text-muted-foreground">Move your library between devices with JSON or CSV exports.</p></div></div><div className="mt-6 flex flex-wrap gap-2"><button data-testid="button-export-data" onClick={backup} className="flex items-center gap-2 rounded-lg border border-border px-4 py-2.5 text-sm font-semibold hover:border-accent"><Database size={15}/> Export JSON</button><button data-testid="button-export-csv" onClick={exportCsv} className="flex items-center gap-2 rounded-lg border border-border px-4 py-2.5 text-sm font-semibold hover:border-accent"><Database size={15}/> Export CSV</button><label className="flex cursor-pointer items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground hover:opacity-90"><Upload size={15}/> Import<input data-testid="input-import-data" type="file" accept=".json,.csv,application/json,text/csv" className="hidden" onChange={e=>{const file=e.target.files?.[0];if(file)importFile(file);e.currentTarget.value='';}}/></label></div></section><section className="rounded-xl border border-destructive/25 bg-destructive/[.03] p-5 md:p-6"><div className="flex items-start gap-4"><div className="rounded-lg bg-destructive/10 p-2.5 text-destructive"><Trash2 size={18}/></div><div><h2 className="font-semibold">Reset workspace</h2><p className="mt-1 text-sm text-muted-foreground">Clear local demo data and return to a blank practice space.</p></div></div><button data-testid="button-reset-workspace" onClick={()=>{if(confirm('Reset your local workspace?')){localStorage.removeItem('cp-problems');setLocal([]);setMessage('Workspace reset.');setLocation('/');}}} className="mt-6 rounded-lg border border-destructive/30 px-4 py-2.5 text-sm font-semibold text-destructive hover:bg-destructive/5">Reset local data</button></section>{message&&<p data-testid="status-settings" className="text-xs text-accent">{message}</p>}</div></Page>;
}

function Router({ user, onLogout }: { user: LocalUser; onLogout: () => void }) { return <Shell user={user} onLogout={onLogout}><Switch><Route path="/" component={Overview}/><Route path="/problems" component={Problems}/><Route path="/collaborator">{() => <Collaborator user={user}/>}</Route><Route path="/contest" component={Contest}/><Route path="/revision" component={Revision}/><Route path="/analytics" component={Analytics}/><Route path="/settings" component={Settings}/><Route component={NotFound}/></Switch></Shell>; }
function App() {
  const [user,setUser]=useState<LocalUser|null>(()=>{try{return JSON.parse(localStorage.getItem('cp-user')||'null') as LocalUser|null;}catch{return null;}});
  if(!user) return <Login onLogin={setUser}/>;
  return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><Router user={user} onLogout={()=>{localStorage.removeItem('cp-user');setUser(null);}}/></WouterRouter><Toaster/></QueryClientProvider>;
}
export default App;